<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jaulas · Agencia Selena</title>
<style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0b141a;color:#e9edef;font:16px system-ui}main{max-width:1200px;margin:auto;padding:24px}header{display:flex;align-items:center;gap:18px;flex-wrap:wrap}a{color:#00d6ae}h1{margin:10px 0}p,small{color:#aebac1}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:18px;margin-top:24px}article{background:#111e24;border:1px solid #34464e;border-radius:14px;padding:20px}h2{font-size:20px}button{background:#00a884;color:white;border:0;border-radius:8px;padding:12px;cursor:pointer;font-weight:700}button:disabled{opacity:.5;cursor:default}label{display:flex;gap:10px;align-items:center;padding:8px 0;border-bottom:1px solid #27373e}input{accent-color:#00a884;width:18px;height:18px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}textarea{width:100%;min-height:240px;background:#0b141a;color:#e9edef;border:1px solid #34464e;border-radius:8px;padding:12px;font:14px/1.6 system-ui}.notice{min-height:24px;color:#71e9cd}.lottery-head{display:flex;align-items:center;gap:16px;margin-bottom:16px}.lottery-logo{object-fit:contain;background:#0b141a;border-radius:18px;padding:6px;border:1px solid #34524b}.report{white-space:pre-wrap;overflow-wrap:anywhere;background:#0a1819;border:1px solid #295249;border-radius:12px;padding:18px;font:15px/1.85 system-ui;margin:14px 0 0;min-height:320px;user-select:text}.grid{align-items:start}article{box-shadow:0 10px 30px #0002;border-top:3px solid #00a884}.actions button:first-child{flex:1}.actions button:last-child{background:#24373e}h2{margin:0}small{display:block;font-size:12px}header{padding-bottom:18px;border-bottom:1px solid #263b42}@media(max-width:420px){main{padding:16px}.grid{grid-template-columns:1fr}article{padding:16px}}</style>
<main><header><a href="index.php">← Volver</a><h1>Jaulas</h1><strong>AG SELENA</strong></header><p>Los 7 animales con más días sin salir de cada lotería. Copia el reporte y compártelo en tu chat.</p><p>Resultados365 · Fuente alternativa: Lotería de Hoy. Se consulta al abrir o pulsar Actualizar.</p><div class="grid" id="grid"></div></main>
<script type="module">
const lotteries={'lotto-activo':'Lotto Activo','guacharoactivo':'GuacharoActivo','selvaplus':'SelvaPlus','guacharito':'Guacharito','la-granjita':'La Granjita','lotto-activo-rd':'Lotto Activo RD','loto-activo-rd-int':'Loto Activo RD INT'};
const logos={"Lotto Activo": "https://resultados365.com/LottoActivo.webp", "Lotto Activo RD": "https://resultados365.com/LottoActivoRD.webp", "Loto Activo RD INT": "https://resultados365.com/LotoActivoRDINT.webp", "GuacharoActivo": "https://resultados365.com/GuacharoActivo.webp", "SelvaPlus": "https://resultados365.com/SelvaPlus.webp", "Monje Millonario": "https://resultados365.com/MonjeMillonario.webp", "Guacharito": "https://resultados365.com/Guacharito.webp", "La Granjita": "https://resultados365.com/LaGranjita.webp"};
for(const [id,name] of Object.entries(lotteries)){
 const card=document.createElement('article');card.innerHTML='<div class="lottery-head"><img class="lottery-logo" width="72" height="72"><h2></h2></div><small class="time"></small><div class="actions"><button class="copy" disabled>Copiar jaulas</button><button class="refresh">Actualizar</button></div><p class="notice" role="status"></p><pre class="report" aria-label="Reporte para copiar"></pre><p><a target="_blank" rel="noopener noreferrer">Ver fuente</a></p>';
 card.querySelector('h2').textContent=name;const logo=card.querySelector('img');logo.src='/imagen.php?url='+encodeURIComponent(logos[name]);logo.alt='Logo '+name;card.querySelector('a').href=`https://resultados365.com/estadisticas/${id}/dias-sin-salir/`;document.querySelector('#grid').append(card);
 const area=card.querySelector('.report'),copy=card.querySelector('.copy'),refresh=card.querySelector('.refresh'),notice=card.querySelector('.notice');let data=[];let date='';
 function report(){const chosen=data.slice(0,7);area.textContent=chosen.length?`*${name}*\n*AG SELENA*\n${date}\n*Reporte de Animales Sin Salir*\n`+chosen.map(x=>`✅ ${x.animal}: ${x.dias} ${x.dias===1?'día':'días'}`).join('\n'):'';copy.disabled=!chosen.length;}
 async function load(){refresh.disabled=true;copy.disabled=true;data=[];area.textContent='';notice.textContent='Consultando…';card.querySelector('.time').textContent='';try{const r=await fetch('/jaulas_api.php?loteria='+id),j=await r.json();if(!r.ok||!j.ok||!j.animales.length)throw Error();data=j.animales.slice(0,7);card.querySelector('a').href=j.fuente;date=new Intl.DateTimeFormat('es-VE',{timeZone:'America/Caracas',day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(j.consultado_en));card.querySelector('.time').textContent='Consultado: '+date+' · '+(j.fuente.includes('loteriadehoy')?'Lotería de Hoy':'Resultados365');report();notice.textContent='';}catch{notice.textContent='No se pudo consultar. Pulsa Actualizar o revisa la fuente.';}finally{refresh.disabled=false;}}
 copy.onclick=async()=>{try{await navigator.clipboard.writeText(area.textContent);notice.textContent='Jaulas copiadas';}catch{const range=document.createRange();range.selectNodeContents(area);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);notice.textContent='Selecciona y copia el reporte con Ctrl+C o manteniendo pulsado.';}};refresh.onclick=load;load();
}
</script></html>
